input.sparql:
PREFIX brick: <http://brickschema.org/schema/1.2/brick#>
SELECT ?s WHERE {
  ?s rdf:type brick:ElectricPowerSensor .
}
LIMIT 100

PREFIX brick: <http://brickschema.org/schema/1.2/brick#>
SELECT DISTINCT ?pred WHERE {
  ?s ?pred ?o .
  FILTER(str(?pred) LIKE "http://brickschema.org%")
}
LIMIT 50

SELECT ?zone ?point ?ts ?label WHERE {
  ?point ?p ?zone .
  ?zone rdfs:label ?label .
  FILTER(CONTAINS(LCASE(?label), "core_top") || CONTAINS(LCASE(?label), "perimeter_top_zn_4"))
  OPTIONAL {
    ?point brick:ref:hasTimeseriesId ?ts
  }
}

SELECT ?sensor ?ts ?ext WHERE {
  ?sensor a brick:ElectricPowerSensor .
  OPTIONAL { ?sensor brick:ref:hasTimeseriesId ?ts }
  OPTIONAL { ?sensor brick:ref:hasExternalReference ?ext }
}

SELECT ?sensor ?zone ?label ?ts WHERE {
  ?sensor rdfs:label ?_ ; ?p ?zone .
  ?zone rdfs:label ?label .
  FILTER(CONTAINS(LCASE(?label), "core_top") || CONTAINS(LCASE(?label), "perimeter_top_zn_4"))
  FILTER(CONTAINS(LCASE(str(?sensor)), "power"))
  OPTIONAL { ?sensor brick:ref:hasTimeseriesId ?ts }
}

SELECT ?sensor ?ts ?ext WHERE {
  ?sensor ?p ?o .
  FILTER(CONTAINS(LCASE(str(?sensor)), "power"))
  OPTIONAL { ?sensor brick:ref:hasTimeseriesId ?ts }
  OPTIONAL { ?sensor brick:ref:hasExternalReference ?ext }
}
